var ComFileDelete = function(fileKey){
	if(!confirm("파일을 삭제하시겠습니까?")) return false;
	
	var ajaxRequest = ComAjaxCall({url:contextPath+"multi/file/delete.do", data:{key:fileKey}});
	ajaxRequest.done(function(resData){
		if( resData && resData.result ){
			alert("삭제되었습니다.");
			fnObj.fnAfterFileDeleteAction();
		}else{
			alert("에러가 발생했습니다.");
		}
	});
	
};


